Avoid redundant type declarations Let the compiler infer types unless explicitly required. // ✅ Preferred
(e1, e2) -> e1.name.compareTo(e2.name);

// ❌ Avoid
(Employee e1, Employee e2) -> e1.name.compareTo(e2.name);

Avoid unnecessary brackets when not required // ✅ Preferred
str -> str.toUpperCase(Locale.US);

// ❌ Avoid
(str) -> str.toUpperCase(Locale.US);

Use a separate method body if the logic is longer // ✅ Preferred
s -> s.toUpperCase(Locale.US);

// As a method
s -> {
    return s.toUpperCase(Locale.US);
}

Avoid method overloading when accepting functional interfaces Method reference/lambda may become ambiguous. // ❌ Avoid
public class Demo<T> {
    public Demo<R> sample(Function<T, R> fn);
    public Demo<T> sample(UnaryOperator<T> fn);
}

// ✅ Use
public class Demo<T> {
    public Demo<R> sample(Function<T, R> fn);
    public Demo<T> sampleDemo(UnaryOperator<T> fn);
}

Example Issue with Ambiguity public interface Calculator {
    String demo(Callable<String> sample1) throws Exception;
    String demo(Supplier<String> sample2);
}

// ❌ Leads to: reference to demo is ambiguous
calculator.demo(() -> "welcome"); ✅ Solution: Use unique method names String demoWithCallable(Callable<String> sample1);
String demoWithSupplier(Supplier<String> sample2);

Use @FunctionalInterface Annotation  // ❌ Avoid
public interface Demo {
    String display();
}

// ✅ Use
@FunctionalInterface
public interface Demo {
    String display();
}

Use Optional primarily as a return type  // ✅ Preferred
Optional<String> name = Optional.empty();

// ❌ Avoid
Optional<String> name = null;

Use functional methods like orElse() ❌ Traditional null check: Demo demo = findKey(k);
if (demo == null) {
    demo = Demo.DEFAULT;
} ✅ Using Optional: Optional<Demo> findKey(String k) { ... }
Demo demo = findKey(k).orElse(Demo.DEFAULT);

Place one stream operation per line  // ❌ Avoid
samples.stream().filter(s -> s.length() > 2).sorted()
    .map(s -> s.substring(0, 2)).collect(Collectors.toList());

// ✅ Use
samples.stream()
    .filter(s -> s.length() > 2)
    .sorted()
    .map(s -> s.substring(0, 2))
    .collect(Collectors.toList());

Use static imports for standard stream methods // ❌ Avoid
samples.stream()
    .sorted(Comparator.reverseOrder())
    .limit(15)
    .collect(Collectors.toMap(Function.identity(), String::length));

// ✅ Use
import static java.util.Comparator.reverseOrder;
import static java.util.function.Function.identity;
import static java.util.stream.Collectors.toMap;

samples.stream()
    .sorted(reverseOrder())
    .limit(15)
    .collect(toMap(identity(), String::length));

Use method references where applicable // ❌ Avoid
samples.stream()
    .map(str -> str.length())
    .collect(toList());

// ✅ Use
samples.stream()
    .map(String::length)
    .collect(toList());
